file.content:
  color: var(--secondary-text-color);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.effect-subtitle {
  margin: 4px 0 0;
  color: var(--secondary-text-color);
  font-size: 0.78rem;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.effect-list {
  margin: 0;
  padding-left: 18px;
  display: grid;
  gap: 4px;
  font-size: 0.9rem;
  line-height: 1.35;
}

.effect-list strong {
  font-weight: 700;
}

.notification-list {
  margin-top: -2px;
}

.history-panel {
  gap: 8px;
}

.history-slot-list,
.history-event-list {
  list-style: none;
  margin: 0;
  padding: 0;

