file.content:
  return this._layout() === "compact";
}

_memberMap(members) {
  const map = new Map();
  for (const member of members) {
    const id = Number(member?.member_id);
    const name = String(member?.name || "").trim();
    if (Number.isInteger(id) && id > 0 && name) {
      map.set(id, name);
    }
  }
  return map;
}

