          )
        : this._findExistingManualSwapReturnWeek(
            scheduleWeeks,
            swapOriginalAssigneeId,
            swapExistingPartnerId,
            swapModalWeek?.week_start
          );
    const swapReturnWeekLabel = swapReturnWeek
      ? this._formatWeekLabelWithDistance(
