              }
              ${compactContext ? `<span class="compact-context">${this._escape(compactContext)}</span>` : ""
              }
            </div>
          </li>
        `;
      })
      .join("");

    const skipCard = compactMode && this._config.eink;

    this._root.innerHTML = `
