                <button class="btn primary" type="button" data-action="submit-done-modal">
                  ${this._modalChoice === "takeover" ? "Confirm takeover" : "Confirm done"}
                </button>
              </div>
            </div>
          </div>
        ` : ""}

        ${!compactMode && this._swapModalOpen && swapModalWeek ? `
