              <div class="modal-actions">
                <button class="btn secondary" type="button" data-action="close-history-modal">Close</button>
              </div>
            </div>
          </div>
        ` : ""}
      ${skipCard ? "" : "</ha-card>"}

      <style>
        ha-card {
          box-shadow: none;
          border: none;
