          display: grid;
          gap: var(--ha-space-2, 8px);
        }

        .card.compact {
          padding: 0;
          gap: var(--ha-space-2, 8px);
        }

        .header {
          display: flex;
          align-items: center;
          padding: var(--ha-space-1, 4px) var(--ha-space-2, 8px) 0;
        }

        .header h2 {
          margin: 0;
