    const swapReturnWeekLabel = swapReturnWeek
      ? this._formatWeekLabelWithDistance(
          swapReturnWeek,
          Math.max(0, scheduleWeeks.findIndex((row) => row.week_start === swapReturnWeek.week_start)),
