    ctxParts.push("This shift was not confirmed as done.");
  }

  if (ctxParts.length) {
    historyContextHtml = `<div class="shift-context">${ctxParts.map((p) => `<p class="shift-context-line">${p}</p>`).join("")}</div>`;
